/**
 * Art catalog: which image to show for a ship, the stardock or a planet.
 * Planet art is generated by tools/art/generate_planets.py.
 */

const SHIP_ART: Record<string, string> = {
  escape_pod: '/ships/escape_pod.webp',
  scout: '/ships/scout.webp',
  trader: '/ships/trader.webp',
  freighter: '/ships/freighter.webp',
  merchant_cruiser: '/ships/merchant_cruiser.webp',
  corporate_flagship: '/ships/corporate_flagship.webp',
  scout_marauder: '/ships/scout_marauder.webp',
  missile_frigate: '/ships/missile_frigate.webp',
  havoc_gunstar: '/ships/havoc_gunstar.webp',
  tholian_sentinel: '/ships/tholian_sentinel.webp',
  interdictor_cruiser: '/ships/interdictor_cruiser.webp',
  stardock: '/ships/stardock.webp',
};

// Planet art, keyed as planet_<name>. Every planet has a _bbs phosphor render.
const PLANET_KEYS = [
  'earth', 'mars',
  'class_m', 'class_k', 'class_o', 'class_l', 'class_c', 'class_h', 'class_u',
  'alien_xenthi', 'alien_vorlak', 'alien_krynn', 'alien_sslith', 'alien_zendarr',
  'alien_thorax', 'alien_quell', 'alien_nebari', 'alien_vedran', 'alien_pyrians',
];
PLANET_KEYS.forEach(k => { SHIP_ART[`planet_${k}`] = `/planets/${k}.webp`; });

// Art with a dedicated BBS render at <name>_bbs.webp
export const HAS_BBS_RENDER = new Set(['stardock', ...PLANET_KEYS.map(k => `planet_${k}`)]);

// Classic TW2002 planet classes. Frontier worlds are desolate.
const FRONTIER_CLASSES = ['m', 'k', 'o', 'l', 'c', 'h', 'u'] as const;
export const PLANET_CLASS_LABEL: Record<string, string> = {
  m: 'Class M, Earth Type (ruined)',
  k: 'Class K, Desert Wasteland',
  o: 'Class O, Toxic Ocean',
  l: 'Class L, Mountainous',
  c: 'Class C, Glacial',
  h: 'Class H, Volcanic',
  u: 'Class U, Gaseous',
};

interface PlanetLike {
  id?: number;
  name?: string | null;
  ownerName?: string | null;
  alienRace?: string | null;
}

/**
 * Picks the art for a planet. Earth and Mars (Terra Corp) and alien
 * homeworlds look alive; every other planet gets a desolate class,
 * fixed per planet id so it always looks the same.
 */
export function planetArtKey(planet: PlanetLike): string {
  if (planet.alienRace) {
    const race = planet.alienRace.toLowerCase();
    if (SHIP_ART[`planet_alien_${race}`]) return `planet_alien_${race}`;
    return 'planet_alien_xenthi';
  }
  const name = (planet.name || '').toLowerCase();
  if (planet.ownerName === 'Terra Corp' && (name === 'earth' || name === 'mars')) {
    return `planet_${name}`;
  }
  return `planet_class_${planetClass(planet)}`;
}

export function planetClass(planet: PlanetLike): string {
  const id = Math.abs(planet.id ?? 0);
  return FRONTIER_CLASSES[id % FRONTIER_CLASSES.length];
}

/** Short description used beside planet art. */
export function planetClassLabel(planet: PlanetLike): string {
  if (planet.alienRace) return `${planet.alienRace} Homeworld`;
  const key = planetArtKey(planet);
  if (key === 'planet_earth') return 'Terra, home of humanity';
  if (key === 'planet_mars') return 'Terra Corp colony';
  return PLANET_CLASS_LABEL[planetClass(planet)];
}

export function shipArtUrl(shipType: string | undefined | null): string | null {
  if (!shipType) return null;
  const key = shipType.toLowerCase().replace(/\s+/g, '_');
  return SHIP_ART[key] || null;
}
